using System.Text.Json.Serialization;
namespace MediaForge.Models;
public sealed class TmdbEpisodeGroupListDto { [JsonPropertyName("results")] public List<TmdbEpisodeGroupSummaryDto> Results { get; set; } = new(); }
public sealed class TmdbEpisodeGroupSummaryDto { [JsonPropertyName("id")] public string Id { get; set; } = ""; [JsonPropertyName("name")] public string Name { get; set; } = ""; [JsonPropertyName("description")] public string? Description { get; set; } [JsonPropertyName("type")] public int Type { get; set; } [JsonPropertyName("episode_count")] public int EpisodeCount { get; set; } [JsonPropertyName("group_count")] public int GroupCount { get; set; } }
public sealed class TmdbEpisodeGroupDetailsDto { [JsonPropertyName("id")] public string Id { get; set; } = ""; [JsonPropertyName("name")] public string Name { get; set; } = ""; [JsonPropertyName("type")] public int Type { get; set; } [JsonPropertyName("groups")] public List<TmdbEpisodeGroupSetDto> Groups { get; set; } = new(); }
public sealed class TmdbEpisodeGroupSetDto { [JsonPropertyName("id")] public string Id { get; set; } = ""; [JsonPropertyName("name")] public string Name { get; set; } = ""; [JsonPropertyName("order")] public int Order { get; set; } [JsonPropertyName("episodes")] public List<TmdbEpisodeGroupEpisodeDto> Episodes { get; set; } = new(); }
public sealed class TmdbEpisodeGroupEpisodeDto { [JsonPropertyName("id")] public int Id { get; set; } [JsonPropertyName("name")] public string Name { get; set; } = ""; [JsonPropertyName("season_number")] public int SeasonNumber { get; set; } [JsonPropertyName("episode_number")] public int EpisodeNumber { get; set; } [JsonPropertyName("order")] public int Order { get; set; } [JsonPropertyName("runtime")] public int? RuntimeMinutes { get; set; } [JsonPropertyName("air_date")] public string? AirDate { get; set; } }
